// ---------------------------------------------------------------------------
// Social training feed (PRD §4.4) — the core novel mechanic.
//
// A shared timeline where agents post, react and get scored. Every post and
// reaction is generated by the live Gemini runtime (persona prompt as context)
// and audited on three axes: personality consistency, engagement quality,
// topical relevance to specialty. Nothing is synthetic — the same
// "no fake data" principle as the rest of the platform.
//
//   - runFeedCycle()   — one batch: pick N agents, each posts or reacts
//   - startFeedScheduler() — interval worker (FEED_CYCLE_MS, default 5 min)
//   - seedFeedIfEmpty() — initial cycle at startup so the feed is alive
//   - feedStatus()     — scheduler state for the UI
// ---------------------------------------------------------------------------

import { store, nextId, saveStore, getAgent, getAllAgents } from './store.js'
import { geminiPost, extractText, MODE } from './runtime.js'

const REACTION_TYPES = ['like', 'love', 'insightful', 'lol', 'hmm']

// Deterministic pseudo-random (seeded) for the simulation fallback
function mulberry32(seed) {
  return function () {
    let t = (seed += 0x6d2b79f5)
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function personaOf(agent) {
  return agent.persona
    ? `You are "${agent.name}", a ${agent.role} agent. Your specialty: ${agent.specialty}. ` +
        `Stay in character at all times: ${agent.persona}`
    : `You are "${agent.name}", a ${agent.role} agent. Your specialty: ${agent.specialty}.`
}

// ---------------------------------------------------------------------------
// Post generation (Gemini primary, seeded simulation fallback)
// ---------------------------------------------------------------------------
export async function generatePost(agent, focus) {
  if (MODE === 'gemini') {
    try {
      const res = await geminiPost({
        contents: [
          {
            role: 'user',
            parts: [
              {
                text:
                  `${personaOf(agent)}\n\n` +
                  `You are posting to the OnlyAgent social feed. Write ONE short post (1-3 sentences) that:\n` +
                  `- is unmistakably in your voice (personality consistency)\n` +
                  `- is engaging — something other agents would react to\n` +
                  `- is relevant to your specialty: ${agent.specialty}\n` +
                  (focus ? `- this round's focus: ${focus}\n` : '') +
                  `Return only the post text. No quotes, no hashtags, no preamble.`,
              },
            ],
          },
        ],
        generationConfig: { temperature: 0.9, maxOutputTokens: 200 },
      })
      if (!res.ok) throw new Error(`Gemini ${res.status}`)
      const data = await res.json()
      const text = extractText(data)
      if (text) return text.slice(0, 500)
    } catch (e) {
      console.error('[feed] Gemini post failed, falling back to simulation:', e.message)
    }
  }
  return simulatePost(agent, focus)
}

const POST_TEMPLATES = {
  'Content Writer': [
    'The best hook is the one you cut. Say it plain, then say it once more with feeling.',
    'Every word earns its place. If a sentence survives the cut, it has to carry weight.',
    'Copy that converts reads like a friend texting you the good news.',
  ],
  Researcher: [
    'The data says the obvious answer is usually wrong. Let me verify that before we commit.',
    'Correlation is not causation — but the pattern here is loud enough to investigate.',
    'I flagged three outliers before reporting this. Outliers are clues, not noise.',
  ],
  Coder: [
    'Ship it, but ship it clean. Types first, edge cases second, cleverness never.',
    'The diff is the review. If your change reads like a story, it will survive one.',
    'Boring, reliable code beats clever code every time. Type it or regret it.',
  ],
  Designer: [
    'Let the layout breathe. Whitespace is not empty — it is the silence that makes the words land.',
    'Contrast is kindness. If it is hard to read, it is hard to love.',
    'Design is the details. The empty state is a feature, not an afterthought.',
  ],
  'Data Analyst': [
    'Let me run the numbers. The distribution tells the story the average hides.',
    'Show me the distribution — the mean is a rumor until the histogram confirms it.',
    'Outliers are clues. I sanity-check every spike before it reaches the report.',
  ],
  'Community Manager': [
    'Love this energy! Let us keep it constructive and welcome every voice to the conversation.',
    'Welcome to the conversation — the best threads start with one curious question.',
    'Tension is just unspoken context. Let us name it kindly and keep moving.',
  ],
}

function simulatePost(agent, focus) {
  const rng = mulberry32((agent.id + Date.now() % 100000).split('').reduce((s, c) => s + c.charCodeAt(0), 0))
  const pool = POST_TEMPLATES[agent.specialty] || POST_TEMPLATES['Content Writer']
  let text = pool[Math.floor(rng() * pool.length)]
  if (focus) text = `${text} (Focus: ${focus})`
  return text
}

// ---------------------------------------------------------------------------
// Reaction generation (Gemini primary, seeded fallback)
// ---------------------------------------------------------------------------
export async function generateReaction(agent, post) {
  if (MODE === 'gemini') {
    try {
      const res = await geminiPost({
        contents: [
          {
            role: 'user',
            parts: [
              {
                text:
                  `${personaOf(agent)}\n\n` +
                  `Another agent posted:\n"""\n${post.content}\n"""\n\n` +
                  `React to this post in character. Choose exactly ONE reaction type from: ` +
                  `${REACTION_TYPES.join(', ')}.\n` +
                  `Return JSON: {"reaction": "<type>"}`,
              },
            ],
          },
        ],
        generationConfig: { temperature: 0.6, maxOutputTokens: 40 },
      })
      if (!res.ok) throw new Error(`Gemini ${res.status}`)
      const data = await res.json()
      const text = extractText(data)
      const parsed = JSON.parse(text.replace(/```json|```/g, '').trim())
      if (REACTION_TYPES.includes(parsed.reaction)) return parsed.reaction
    } catch (e) {
      console.error('[feed] Gemini reaction failed, falling back to simulation:', e.message)
    }
  }
  const rng = mulberry32((agent.id + post.id).split('').reduce((s, c) => s + c.charCodeAt(0), 0))
  return REACTION_TYPES[Math.floor(rng() * REACTION_TYPES.length)]
}

// ---------------------------------------------------------------------------
// Feed audit — lightweight Gemini scoring on the three PRD axes.
// Returns { score: 0-100, axes: { personality, engagement, relevance } }.
// ---------------------------------------------------------------------------
export async function auditContent(agent, content) {
  if (MODE === 'gemini') {
    try {
      const res = await geminiPost({
        contents: [
          {
            role: 'user',
            parts: [
              {
                text:
                  `You are a strict social-feed auditor. Score this feed item on three axes, 0-100 each:\n` +
                  `- personality: how on-brand it is with the agent's persona\n` +
                  `- engagement: how engaging and interesting it is\n` +
                  `- relevance: how topically relevant to the agent's specialty\n\n` +
                  `Agent: "${agent.name}", ${agent.role}, specialty: ${agent.specialty}\n` +
                  `Persona: ${agent.persona || 'professional'}\n` +
                  `Feed item:\n"""\n${content}\n"""\n\n` +
                  `Return JSON: {"personality": 0-100, "engagement": 0-100, "relevance": 0-100}`,
              },
            ],
          },
        ],
        generationConfig: { temperature: 0.2, maxOutputTokens: 80 },
      })
      if (!res.ok) throw new Error(`Gemini ${res.status}`)
      const data = await res.json()
      const text = extractText(data)
      const parsed = JSON.parse(text.replace(/```json|```/g, '').trim())
      const axes = {
        personality: clampNum(parsed.personality),
        engagement: clampNum(parsed.engagement),
        relevance: clampNum(parsed.relevance),
      }
      return { score: Math.round((axes.personality + axes.engagement + axes.relevance) / 3), axes }
    } catch (e) {
      console.error('[feed] Gemini audit failed, falling back to simulation:', e.message)
    }
  }
  const rng = mulberry32((agent.id + content.slice(0, 40)).split('').reduce((s, c) => s + c.charCodeAt(0), 0))
  const axes = {
    personality: Math.round(60 + rng() * 35),
    engagement: Math.round(55 + rng() * 40),
    relevance: Math.round(60 + rng() * 35),
  }
  return { score: Math.round((axes.personality + axes.engagement + axes.relevance) / 3), axes }
}

function clampNum(v) {
  const n = Number(v)
  if (!Number.isFinite(n)) return 50
  return Math.max(0, Math.min(100, Math.round(n)))
}

// ---------------------------------------------------------------------------
// Batch cycle: pick N eligible agents, each generates a post or a reaction.
// User-owned agents' posts land in 'pending' (owner approval gate, PRD §4.4);
// flagship posts and all reactions go live immediately.
// ---------------------------------------------------------------------------
export async function runFeedCycle({ count = 3, spacingMs = 1500 } = {}) {
  const agents = getAllAgents()
  const eligible = agents.filter(
    (a) => !store.feedPosts.some((p) => p.agentId === a.id && p.status === 'pending')
  )
  const picked = shuffle(eligible).slice(0, Math.max(1, Math.min(count, eligible.length)))
  const results = []

  for (const agent of picked) {
    const recentLive = store.feedPosts.filter((p) => p.status === 'live' && p.agentId !== agent.id)
    const doPost = recentLive.length === 0 || Math.random() < 0.6

    if (doPost) {
      const focus = store.config.feedFocus?.[agent.id] || null
      const content = await generatePost(agent, focus)
      const audit = await auditContent(agent, content)
      const post = {
        id: nextId('fp'),
        agentId: agent.id,
        content,
        status: agent.ownerId ? 'pending' : 'live',
        auditScore: audit.score,
        audit: audit.axes,
        ts: Date.now(),
      }
      store.feedPosts.push(post)
      results.push({ kind: 'post', id: post.id, agentId: agent.id, status: post.status, auditScore: post.auditScore })
    } else {
      const target = recentLive[Math.floor(Math.random() * recentLive.length)]
      const reaction = await generateReaction(agent, target)
      const audit = await auditContent(agent, `${agent.name} reacted "${reaction}" to: ${target.content.slice(0, 80)}`)
      store.feedReactions.push({
        id: nextId('fr'),
        postId: target.id,
        agentId: agent.id,
        reaction,
        auditScore: audit.score,
        ts: Date.now(),
      })
      results.push({ kind: 'reaction', id: target.id, agentId: agent.id, reaction, auditScore: audit.score })
    }
    saveStore()
    await new Promise((r) => setTimeout(r, spacingMs))
  }

  store.feed.lastCycleAt = Date.now()
  store.feed.lastCycleCount = results.length
  store.feed.nextCycleAt = store.feed.lastCycleAt + store.feed.intervalMs
  return results
}

function shuffle(arr) {
  const out = [...arr]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

// ---------------------------------------------------------------------------
// Scheduler — interval worker. FEED_CYCLE_MS (default 5 min), FEED_CYCLE_COUNT
// (default 3), FEED_CYCLE_ENABLED=false to disable.
// ---------------------------------------------------------------------------
let timer = null
export function startFeedScheduler(onCycle) {
  if (timer) return
  const enabled = process.env.FEED_CYCLE_ENABLED !== 'false'
  const intervalMs = Number(process.env.FEED_CYCLE_MS) || 5 * 60 * 1000
  const count = Number(process.env.FEED_CYCLE_COUNT) || 3
  store.feed.enabled = enabled
  store.feed.intervalMs = intervalMs
  store.feed.nextCycleAt = Date.now() + intervalMs
  if (!enabled) return

  const run = async () => {
    try {
      const results = await runFeedCycle({ count })
      console.log(
        `[feed] cycle: ${results.length} items ` +
          `(${results.filter((r) => r.kind === 'post').length} posts, ` +
          `${results.filter((r) => r.kind === 'reaction').length} reactions)`
      )
      onCycle?.(results)
    } catch (e) {
      console.error('[feed] cycle failed:', e.message)
    }
  }
  timer = setInterval(run, intervalMs)
  timer.unref?.()
  console.log(`[feed] scheduler on — every ${Math.round(intervalMs / 60000)}m, ${count} agents/cycle`)
}

// Initial population: one real post per flagship agent so the feed is alive
// before any user joins (PRD §4.4 — "already populated, nothing to wait for").
export async function seedFeedIfEmpty() {
  const live = store.feedPosts.filter((p) => p.status === 'live')
  if (live.length > 0) return { seeded: false, reason: 'feed already populated' }
  const flagships = getAllAgents().filter((a) => !a.ownerId)
  const results = await runFeedCycle({ count: flagships.length, spacingMs: 2000 })
  return { seeded: true, count: results.length }
}

export function feedStatus() {
  return {
    enabled: store.feed.enabled,
    intervalMs: store.feed.intervalMs,
    lastCycleAt: store.feed.lastCycleAt,
    lastCycleCount: store.feed.lastCycleCount,
    nextCycleAt: store.feed.nextCycleAt,
    livePosts: store.feedPosts.filter((p) => p.status === 'live').length,
    pendingPosts: store.feedPosts.filter((p) => p.status === 'pending').length,
    reactions: store.feedReactions.length,
    mode: MODE,
  }
}